-- P1 auth review round 5, rule lock-order (topics db-r1-2, db-r4-1, db-r4-2).
--
-- Two phone functions broke the global lock order (internal/lockrank, spec 4.4)
-- and one of them the strength rule:
--
--   * auth_phone_change_complete locked the request first and the user second, the
--     other way round from every credential writer (a login, a password change and
--     the one-time re-issue lock the user first), so a phone change racing a
--     re-issue could wait on each other.
--   * both it and auth_phone_mark_verified took FOR UPDATE on users, which
--     conflicts with the FOR KEY SHARE that every insert into sessions or
--     refresh_tokens takes on the user through its foreign key (db-r4-1). Neither
--     changes the key it locks on before the last statement, and the last one is a
--     write the server upgrades on its own, after the user was locked first, so
--     FOR NO KEY UPDATE keeps the mutual exclusion the functions need.
--
-- The request is now read without a lock to learn whose it is, the user is locked,
-- and then the request, which is re-read under its lock so a concurrent completion
-- is still seen. Outcomes are unchanged.
--
-- A new file and not an edit of an applied one (README, Rules).

-- +goose Up

SET LOCAL search_path = pg_catalog;

SET ROLE ctrlz_auth;

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION ctrlz_fn.auth_phone_change_complete(p_request_id uuid)
RETURNS TABLE (outcome text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  v_tenant uuid := ctrlz.current_tenant_id();
  v_user   uuid;
  r        record;
  v_old    text;
BEGIN
  IF v_tenant IS NULL THEN
    RETURN;
  END IF;

  -- Whose request it is, without a lock: the user row comes first in the lock
  -- order, and its id is only known from here.
  SELECT p.user_id INTO v_user
  FROM ctrlz.phone_change_requests p
  WHERE p.tenant_id = v_tenant AND p.id = p_request_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;

  SELECT u.phone_e164 INTO v_old
  FROM ctrlz.users u
  WHERE u.tenant_id = v_tenant AND u.id = v_user
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;

  SELECT p.new_phone_e164, p.old_otp_id, p.new_otp_id, p.expires_at, p.completed_at, p.created_at
  INTO r
  FROM ctrlz.phone_change_requests p
  WHERE p.tenant_id = v_tenant AND p.id = p_request_id
  FOR UPDATE;
  IF NOT FOUND OR r.completed_at IS NOT NULL OR r.expires_at <= pg_catalog.now() THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;

  PERFORM 1 FROM ctrlz.otp_challenges o
  WHERE o.id = r.old_otp_id AND o.phone_e164 = v_old AND o.purpose = 'phone_old'
    AND o.consumed_at >= r.created_at AND o.consumed_at > pg_catalog.now() - interval '10 minutes';
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;
  PERFORM 1 FROM ctrlz.otp_challenges o
  WHERE o.id = r.new_otp_id AND o.phone_e164 = r.new_phone_e164 AND o.purpose = 'phone_new'
    AND o.consumed_at >= r.created_at AND o.consumed_at > pg_catalog.now() - interval '10 minutes';
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;

  BEGIN
    UPDATE ctrlz.users u SET phone_e164 = r.new_phone_e164, phone_verified_at = pg_catalog.now()
    WHERE u.tenant_id = v_tenant AND u.id = v_user;
    UPDATE ctrlz.phone_change_requests p SET completed_at = pg_catalog.now()
    WHERE p.tenant_id = v_tenant AND p.id = p_request_id;
  EXCEPTION WHEN unique_violation THEN
    -- The number belongs to someone else. Only a person who holds that SIM
    -- gets this far, so the outcome may say so.
    RETURN QUERY SELECT 'unavailable'::text;
    RETURN;
  END;

  RETURN QUERY SELECT 'ok'::text;
END
$$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE OR REPLACE FUNCTION ctrlz_fn.auth_phone_mark_verified(p_user_id uuid, p_otp_id uuid)
RETURNS TABLE (outcome text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
AS $$
DECLARE
  v_tenant   uuid := ctrlz.current_tenant_id();
  v_phone    text;
  v_verified timestamptz;
BEGIN
  IF v_tenant IS NULL THEN
    RETURN;
  END IF;

  SELECT u.phone_e164, u.phone_verified_at INTO v_phone, v_verified
  FROM ctrlz.users u
  WHERE u.tenant_id = v_tenant AND u.id = p_user_id
  FOR NO KEY UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;
  IF v_verified IS NOT NULL THEN
    RETURN QUERY SELECT 'ok'::text;
    RETURN;
  END IF;

  PERFORM 1 FROM ctrlz.otp_challenges o
  WHERE o.id = p_otp_id AND o.phone_e164 = v_phone AND o.purpose IN ('login', 'reset')
    AND o.consumed_at IS NOT NULL AND o.consumed_at > pg_catalog.now() - interval '10 minutes';
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'invalid'::text;
    RETURN;
  END IF;

  UPDATE ctrlz.users u SET phone_verified_at = pg_catalog.now()
  WHERE u.tenant_id = v_tenant AND u.id = p_user_id AND u.phone_verified_at IS NULL;
  RETURN QUERY SELECT 'ok'::text;
END
$$;
-- +goose StatementEnd

RESET ROLE;
